import{_ as e,o as a,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Community Google Summer of Code 2025 Intern Showcase","description":"","frontmatter":{"title":"Ceph Community Google Summer of Code 2025 Intern Showcase","date":"2025-10-09T00:00:00.000Z","updated":"2025-10-10T00:00:00.000Z","tags":["Ceph","Google Summer of Code","分布式存储","存储","开源"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Community_Google_Summer_of_Code_2025_Intern_Showcase.md","filePath":"posts/2025/Ceph_Community_Google_Summer_of_Code_2025_Intern_Showcase.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Ceph_Community_Google_Summer_of_Code_2025_Intern_Showcase.md"};function i(l,o,s,h,d,u){return a(),t("div",null,[...o[0]||(o[0]=[r('<h3 id="ceph-community-google-summer-of-code-2025-intern-showcase-纪要" tabindex="-1">Ceph Community Google Summer of Code 2025 Intern Showcase 纪要 <a class="header-anchor" href="#ceph-community-google-summer-of-code-2025-intern-showcase-纪要" aria-label="Permalink to &quot;Ceph Community Google Summer of Code 2025 Intern Showcase 纪要&quot;">​</a></h3><h4 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h4><ul><li><strong>时间</strong>：2025年</li><li><strong>主持人</strong>：Anthony D&#39;Atri (Ceph 基金会社区经理)</li><li><strong>形式</strong>：线上展示会</li><li><strong>主题</strong>：2025年 Ceph 社区 GSoC 实习生项目成果展示</li></ul><h4 id="展示项目详情" tabindex="-1">展示项目详情 <a class="header-anchor" href="#展示项目详情" aria-label="Permalink to &quot;展示项目详情&quot;">​</a></h4><h5 id="_1-rgw-持久化桶通知的分片优化-adish" tabindex="-1">1. RGW 持久化桶通知的分片优化 (Adish) <a class="header-anchor" href="#_1-rgw-持久化桶通知的分片优化-adish" aria-label="Permalink to &quot;1. RGW 持久化桶通知的分片优化 (Adish)&quot;">​</a></h5><ul><li><strong>核心贡献</strong>：改进 RGW 的 bucket notification 流程，提高可扩展性和负载均衡性</li><li><strong>关键技术</strong>：引入分片机制，通过哈希 bucket key 和 object key 确定目标分片</li><li><strong>性能提升</strong>：小对象吞吐量提升约一倍，延迟显著降低</li><li><strong>状态</strong>：已合并到上游</li></ul><h5 id="_2-rgw-api-模糊测试框架集成-sash" tabindex="-1">2. RGW API 模糊测试框架集成 (Sash) <a class="header-anchor" href="#_2-rgw-api-模糊测试框架集成-sash" aria-label="Permalink to &quot;2. RGW API 模糊测试框架集成 (Sash)&quot;">​</a></h5><ul><li><strong>核心贡献</strong>：集成 Microsoft RESTler 模糊测试工具，检测 RGW API 安全漏洞</li><li><strong>关键技术</strong>：实现签名认证，开发 policy fuzzing 代理服务器</li><li><strong>发现的关键漏洞</strong>：AMZ copy source 头为空时导致 RGW 崩溃</li><li><strong>测试范围</strong>：覆盖 bucket/object 操作和策略端点</li></ul><h5 id="_3-ceph-dashboard-通知系统重构-anik" tabindex="-1">3. Ceph Dashboard 通知系统重构 (Anik) <a class="header-anchor" href="#_3-ceph-dashboard-通知系统重构-anik" aria-label="Permalink to &quot;3. Ceph Dashboard 通知系统重构 (Anik)&quot;">​</a></h5><ul><li><strong>核心贡献</strong>：基于 Carbon Design System 重建通知系统，提供静音功能、统一面板、全局搜索等</li><li><strong>用户体验提升</strong>：避免频繁切换 CLI 和 Dashboard，关键警报不会丢失</li></ul><h5 id="_4-ceph-测试集群容器化方案-paret" tabindex="-1">4. Ceph 测试集群容器化方案 (Paret) <a class="header-anchor" href="#_4-ceph-测试集群容器化方案-paret" aria-label="Permalink to &quot;4. Ceph 测试集群容器化方案 (Paret)&quot;">​</a></h5><ul><li><strong>核心贡献</strong>：开发 <code>ceph-deck</code> 工具，使用 rootless Podman 容器本地化部署 Ceph 集群</li><li><strong>解决的核心问题</strong>：降低新贡献者门槛，支持本地运行集成测试</li></ul><h4 id="关键讨论要点" tabindex="-1">关键讨论要点 <a class="header-anchor" href="#关键讨论要点" aria-label="Permalink to &quot;关键讨论要点&quot;">​</a></h4><ul><li><strong>分片设计的兼容性</strong>：新旧设计可共存，不进行 resharding</li><li><strong>安全测试的价值</strong>：建立自动化回归防护，发现关键漏洞</li><li><strong>容器化方案选择</strong>：采用 rootless Podman，支持远程集群部署</li></ul><h4 id="行动项" tabindex="-1">行动项 <a class="header-anchor" href="#行动项" aria-label="Permalink to &quot;行动项&quot;">​</a></h4><ul><li><strong>社区推广</strong>：分享项目博客，组织技术分享会</li><li><strong>代码整合</strong>：完善文档和测试用例，确保新功能平滑集成</li><li><strong>持续开发</strong>：扩展模糊测试覆盖范围，贡献通知组件，完善设备自动发现功能</li></ul><h4 id="特别致谢" tabindex="-1">特别致谢 <a class="header-anchor" href="#特别致谢" aria-label="Permalink to &quot;特别致谢&quot;">​</a></h4><ul><li>感谢所有导师的指导，祝贺实习生成功完成项目</li><li>鼓励参与者继续贡献，期待在 CephCon 等活动中交流</li></ul>',18)])])}const m=e(n,[["render",i]]);export{g as __pageData,m as default};
